-- Connected groups integration. Every fixture, notification and ledger posting is rolled back.
begin;
create function pg_temp.group_assert(value boolean,label text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'Connected groups failed: %',label;end if;perform set_config('lumo.group.checks',(coalesce(nullif(current_setting('lumo.group.checks',true),''),'0')::integer+1)::text,true);end $$;
create function pg_temp.group_call(command text,payload jsonb default '{}') returns jsonb language plpgsql as $$
declare result jsonb;
begin execute 'set local role authenticated';result:=public.lumo_rpc(command,payload);execute 'reset role';return result;exception when others then execute 'reset role';raise;end $$;
create function pg_temp.group_as(p_user uuid,p_session uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',p_user,'role','authenticated','session_id',p_session)::text,true);end $$;
do $$
declare
 owner_id uuid:=gen_random_uuid();alice_id uuid:=gen_random_uuid();bob_id uuid:=gen_random_uuid();outside_id uuid:=gen_random_uuid();
 owner_session uuid:=gen_random_uuid();alice_session uuid:=gen_random_uuid();bob_session uuid:=gen_random_uuid();outside_session uuid:=gen_random_uuid();
 pin text:=lpad(floor(random()*1000000)::integer::text,6,'0');suffix text:=substr(replace(gen_random_uuid()::text,'-',''),1,8);
 owner_handle text:='grp_owner_'||suffix;alice_handle text:='grp_alice_'||suffix;bob_handle text:='grp_bob_'||suffix;outside_handle text:='grp_other_'||suffix;
 result jsonb;first_result jsonb;snapshot jsonb;gid uuid;gid2 uuid;gid3 uuid;pid uuid;pid2 uuid;group_account uuid;owner_account uuid;alice_account uuid;bob_account uuid;outside_account uuid;
 code text;before_count bigint;before_balance bigint;
begin
 perform set_config('lumo.group.checks','0',true);
 insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,created_at,updated_at) values
 (owner_id,'authenticated','authenticated',owner_handle||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now()),
 (alice_id,'authenticated','authenticated',alice_handle||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now()),
 (bob_id,'authenticated','authenticated',bob_handle||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now()),
 (outside_id,'authenticated','authenticated',outside_handle||'@example.invalid',now(),'{"lumo_pilot":true}',now(),now());
 insert into auth.sessions(id,user_id,created_at,updated_at) values(owner_session,owner_id,now(),now()),(alice_session,alice_id,now(),now()),(bob_session,bob_id,now(),now()),(outside_session,outside_id,now(),now());
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('account.open',jsonb_build_object('handle',owner_handle,'displayName','Owner fixture','pin',pin));owner_account:=(result#>>'{account,id}')::uuid;
 result:=pg_temp.group_call('wallet.fund',jsonb_build_object('amount',10000,'confirmSandbox',true,'attemptId','group-owner-fund-'||suffix));perform pg_temp.group_assert(result->>'ok'='true','owner explicit test funding');
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('account.open',jsonb_build_object('handle',alice_handle,'displayName','Alice fixture','pin',pin));alice_account:=(result#>>'{account,id}')::uuid;
 result:=pg_temp.group_call('wallet.fund',jsonb_build_object('amount',10000,'confirmSandbox',true,'attemptId','group-alice-fund-'||suffix));perform pg_temp.group_assert(result->>'ok'='true','Alice explicit test funding');
 perform pg_temp.group_as(bob_id,bob_session);
 result:=pg_temp.group_call('account.open',jsonb_build_object('handle',bob_handle,'displayName','Bob fixture','pin',pin));bob_account:=(result#>>'{account,id}')::uuid;
 result:=pg_temp.group_call('wallet.fund',jsonb_build_object('amount',10000,'confirmSandbox',true,'attemptId','group-bob-fund-'||suffix));perform pg_temp.group_assert(result->>'ok'='true','Bob explicit test funding');
 perform pg_temp.group_as(outside_id,outside_session);
 result:=pg_temp.group_call('account.open',jsonb_build_object('handle',outside_handle,'displayName','Other fixture','pin',pin));outside_account:=(result#>>'{account,id}')::uuid;
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.create',jsonb_build_object('name','Legon field trip','description','Shared fixture','target',50000,'approvalCount',2,'approvalThreshold',1000,'deadline',to_char(now()+interval '10 days','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'attemptId','group-create-'||suffix));first_result:=result;gid:=(result->>'groupId')::uuid;group_account:=(result#>>'{group,accountId}')::uuid;code:=result#>>'{group,joinCode}';
 perform pg_temp.group_assert(result->>'ok'='true' and gid is not null and length(code)=32 and (result#>>'{group,balance}')::bigint=0,'group creates separate empty account and private join code');
 perform pg_temp.group_assert((select kind from lumo_private.accounts where id=group_account)='group' and group_account<>owner_account,'group funds separate from personal consumer account');
 result:=pg_temp.group_call('group.create',jsonb_build_object('name','Legon field trip','description','Shared fixture','target',50000,'approvalCount',2,'approvalThreshold',1000,'deadline',to_char(now()+interval '10 days','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'attemptId','group-create-'||suffix));
 perform pg_temp.group_assert(result->>'replayed'='true' and result->>'groupId'=gid::text,'lost create response replays exact group');
 result:=pg_temp.group_call('group.create',jsonb_build_object('name','Changed','attemptId','group-create-'||suffix));perform pg_temp.group_assert(result->>'code'='IDEMPOTENCY_MISMATCH','same create attempt cannot change group');
 result:=pg_temp.group_call('group.create',jsonb_build_object('name','Bad mandate','approvalCount',1.5,'attemptId','group-bad-mandate-'||suffix));perform pg_temp.group_assert(result->>'code'='INVALID_MANDATE','fractional mandate rejected');
 result:=pg_temp.group_call('group.create',jsonb_build_object('name','Bad date','deadline','not-a-date','attemptId','group-bad-date-'||suffix));perform pg_temp.group_assert(result->>'code'='INVALID_DEADLINE','invalid deadline rejected');
 perform pg_temp.group_as(outside_id,outside_session);
 result:=pg_temp.group_call('group.list');perform pg_temp.group_assert(result->'groups'='[]'::jsonb,'outsider group list empty');
 result:=pg_temp.group_call('group.get',jsonb_build_object('groupId',gid));perform pg_temp.group_assert(result->>'code'='GROUP_FORBIDDEN','outsider cannot retrieve private group');
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.invite',jsonb_build_object('groupId',gid,'handle',alice_handle,'attemptId','group-invite-alice-'||suffix));perform pg_temp.group_assert(result->>'ok'='true','owner invites exact existing handle');
 result:=pg_temp.group_call('group.respond',jsonb_build_object('groupId',gid,'accept',true,'attemptId','group-owner-self-accept-'||suffix));perform pg_temp.group_assert(result->>'code'='INVITATION_UNAVAILABLE','owner cannot accept another member invitation');
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.list');snapshot:=result#>'{groups,0}';perform pg_temp.group_assert(snapshot->>'membershipStatus'='invited' and not(snapshot?'balance') and not(snapshot?'joinCode') and not(snapshot?'accountId'),'unaccepted invitation reveals no funds or private code');
 result:=pg_temp.group_call('group.get',jsonb_build_object('groupId',gid));perform pg_temp.group_assert(result->>'code'='GROUP_FORBIDDEN','invitee cannot read chat or activity before consent');
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',100,'pin',pin,'attemptId','group-unaccepted-pay-'||suffix));perform pg_temp.group_assert(result->>'code'='GROUP_FORBIDDEN','invitee cannot contribute before consent');
 result:=pg_temp.group_call('group.respond',jsonb_build_object('groupId',gid,'accept',true,'attemptId','group-accept-alice-'||suffix));perform pg_temp.group_assert(result->>'accepted'='true' and result#>>'{group,membershipStatus}'='active','invitee explicitly accepts shared membership');
 result:=pg_temp.group_call('group.get',jsonb_build_object('groupId',gid));perform pg_temp.group_assert(not(result->'group'?'joinCode'),'member cannot retrieve owner join secret');
 result:=pg_temp.group_call('group.invite',jsonb_build_object('groupId',gid,'handle',bob_handle,'attemptId','group-member-invite-'||suffix));perform pg_temp.group_assert(result->>'code'='GROUP_FORBIDDEN','ordinary member cannot grant membership');
 perform pg_temp.group_as(bob_id,bob_session);
 result:=pg_temp.group_call('group.join',jsonb_build_object('code',code,'attemptId','group-join-bob-'||suffix));perform pg_temp.group_assert(result->>'ok'='true' and result#>>'{group,membershipStatus}'='active','private code opt-in joins correct group');
 perform pg_temp.group_as(outside_id,outside_session);
 result:=pg_temp.group_call('group.join',jsonb_build_object('code','0123','attemptId','group-bad-code-'||suffix));perform pg_temp.group_assert(result->>'code'='GROUP_NOT_FOUND','predictable short code rejected');
 result:=pg_temp.group_call('group.join',jsonb_build_object('code',code,'attemptId','group-join-other-'||suffix));perform pg_temp.group_assert(result->>'ok'='true','another person may explicitly join shared code');
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.member.remove',jsonb_build_object('groupId',gid,'handle',outside_handle,'attemptId','group-remove-other-'||suffix));perform pg_temp.group_assert(result->>'ok'='true','owner removes a member');
 perform pg_temp.group_as(outside_id,outside_session);
 result:=pg_temp.group_call('group.join',jsonb_build_object('code',code,'attemptId','group-rejoin-removed-'||suffix));perform pg_temp.group_assert(result->>'code'='GROUP_FORBIDDEN','removed member cannot regain access through old code');
 result:=pg_temp.group_call('group.get',jsonb_build_object('groupId',gid));perform pg_temp.group_assert(result->>'code'='GROUP_FORBIDDEN','removed member cannot read future group data');
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',5000,'pin',pin,'attemptId','group-owner-contribute-'||suffix));first_result:=result;
 perform pg_temp.group_assert(result->>'ok'='true' and result#>>'{receipt,type}'='group_contribution' and (result#>>'{group,balance}')::bigint=5000 and (result#>>'{account,balance}')::bigint=5000,'contribution posts paired real ledger and exact consumer/group balances');
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',5000,'pin',pin,'attemptId','group-owner-contribute-'||suffix));perform pg_temp.group_assert(result->>'replayed'='true' and result#>>'{receipt,id}'=first_result#>>'{receipt,id}','retry contribution charges exactly once');
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',1.5,'pin',pin,'attemptId','group-fractional-'||suffix));perform pg_temp.group_assert(result->>'code'='INVALID_AMOUNT','fractional pesewa contribution rejected');
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',100,'pin','wrong','attemptId','group-bad-pin-'||suffix));perform pg_temp.group_assert(result->>'ok'='false' and (select balance from lumo_private.accounts where id=group_account)=5000,'invalid PIN cannot move group money');
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',3000,'pin',pin,'attemptId','group-alice-contribute-'||suffix));perform pg_temp.group_assert(result->>'ok'='true' and (result#>>'{account,balance}')::bigint=7000,'Alice contribution debits shared balance');
 result:=pg_temp.group_call('group.message',jsonb_build_object('groupId',gid,'text','Bus quote is ready.','attemptId','group-message-'||suffix));perform pg_temp.group_assert(result->>'ok'='true','member posts real shared chat message');
 result:=pg_temp.group_call('group.message',jsonb_build_object('groupId',gid,'text','Changed duplicate','attemptId','group-message-'||suffix));perform pg_temp.group_assert(result->>'code'='IDEMPOTENCY_MISMATCH','message retry cannot rewrite content');
 perform pg_temp.group_as(bob_id,bob_session);
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',2000,'pin',pin,'attemptId','group-bob-contribute-'||suffix));perform pg_temp.group_assert((result#>>'{group,balance}')::bigint=10000 and (result#>>'{account,balance}')::bigint=8000,'third device sees conserved total without personal group-fund mixing');
 result:=pg_temp.group_call('group.get',jsonb_build_object('groupId',gid));perform pg_temp.group_assert(exists(select 1 from jsonb_array_elements(result#>'{group,messages}')x where x->>'text'='Bus quote is ready.'),'another member sees exact real chat message');
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.payout.request',jsonb_build_object('groupId',gid,'recipientHandle',owner_handle,'amount',3000,'note','Bus deposit','pin',pin,'attemptId','group-payout-request-'||suffix));pid:=(result->>'proposalId')::uuid;
 perform pg_temp.group_assert(result->>'ok'='true' and (result#>>'{proposal,requiredApprovals}')::integer=2 and (result#>>'{proposal,approvals}')::integer=0 and not(result?'receipt'),'large payout snapshots two OTHER approvals without moving money');
 perform pg_temp.group_assert((select balance from lumo_private.accounts where id=group_account)=10000 and (select balance from lumo_private.accounts where id=owner_account)=5000,'payout request never credits pending money');
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-self-approve-'||suffix));perform pg_temp.group_assert(result->>'code'='APPROVAL_FORBIDDEN','requester cannot approve own payout');
 result:=pg_temp.group_call('group.member.remove',jsonb_build_object('groupId',gid,'handle',bob_handle,'attemptId','group-remove-pending-'||suffix));perform pg_temp.group_assert(result->>'code'='PENDING_PAYOUT','membership cannot undermine a pending mandate');
 result:=pg_temp.group_call('group.cancel',jsonb_build_object('groupId',gid,'pin',pin,'attemptId','group-cancel-pending-'||suffix));perform pg_temp.group_assert(result->>'code'='PENDING_PAYOUT','cannot cancel collection while a payout needs decision');
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-alice-approve-'||suffix));perform pg_temp.group_assert(result#>>'{proposal,status}'='pending' and (result#>>'{proposal,approvals}')::integer=1 and not(result?'receipt'),'first approval remains pending with no debit');
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-alice-double-'||suffix));perform pg_temp.group_assert(result->>'code'='ALREADY_APPROVED','one member cannot vote twice under different attempts');
 result:=pg_temp.group_call('group.leave',jsonb_build_object('groupId',gid,'attemptId','group-leave-pending-'||suffix));perform pg_temp.group_assert(result->>'code'='PENDING_PAYOUT','leaving cannot break a pending quorum');
 perform pg_temp.group_as(bob_id,bob_session);
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-bob-approve-'||suffix));first_result:=result;
 perform pg_temp.group_assert(result#>>'{proposal,status}'='paid' and result#>>'{receipt,type}'='group_payout' and (result#>>'{group,balance}')::bigint=7000,'final approval posts one authoritative payout');
 perform pg_temp.group_assert((select balance from lumo_private.accounts where id=owner_account)=8000,'intended consumer recipient gets exact payout');
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-bob-approve-'||suffix));perform pg_temp.group_assert(result->>'replayed'='true' and result#>>'{receipt,id}'=first_result#>>'{receipt,id}','lost approval response recovers same posted payout');
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-paid-again-'||suffix));perform pg_temp.group_assert(result->>'code'='PAYOUT_UNAVAILABLE','new attempt cannot pay completed proposal again');
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.payout.request',jsonb_build_object('groupId',gid,'recipientHandle',outside_handle,'amount',1000,'pin',pin,'attemptId','group-small-payout-'||suffix));pid2:=(result->>'proposalId')::uuid;perform pg_temp.group_assert((result#>>'{proposal,requiredApprovals}')::integer=1,'small payout still needs one other member');
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid2,'pin',pin,'attemptId','group-small-approve-'||suffix));perform pg_temp.group_assert(result#>>'{proposal,status}'='paid' and (result#>>'{group,balance}')::bigint=6000,'small payout posted after another person approves');
 -- Cumulative low-value splitting cannot bypass the higher mandate.
 result:=pg_temp.group_call('group.payout.request',jsonb_build_object('groupId',gid,'recipientHandle',outside_handle,'amount',500,'pin',pin,'attemptId','group-split-request-'||suffix));pid:=(result->>'proposalId')::uuid;
 perform pg_temp.group_assert((result#>>'{proposal,requiredApprovals}')::integer=2,'split same-recipient payouts count cumulatively over twenty-four hours');
 result:=pg_temp.group_call('group.invite',jsonb_build_object('groupId',gid,'handle',outside_handle,'attemptId','group-reinvite-new-voter-'||suffix));
 perform pg_temp.group_as(outside_id,outside_session);
 result:=pg_temp.group_call('group.respond',jsonb_build_object('groupId',gid,'accept',true,'attemptId','group-new-voter-accept-'||suffix));
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-new-voter-approve-'||suffix));
 perform pg_temp.group_assert(result->>'code'='APPROVAL_FORBIDDEN','member joining later cannot approve an older request');
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.payout.cancel',jsonb_build_object('groupId',gid,'proposalId',pid,'attemptId','group-split-cancel-'||suffix));
 perform pg_temp.group_assert(result->>'ok'='true' and result#>>'{proposal,status}'='cancelled','requester can cancel without moving group funds');
 -- An unavailable destination rolls back the would-be final approval as well as all ledger changes.
 result:=pg_temp.group_call('group.payout.request',jsonb_build_object('groupId',gid,'recipientHandle',outside_handle,'amount',4000,'pin',pin,'attemptId','group-failure-request-'||suffix));pid:=(result->>'proposalId')::uuid;
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-failure-first-vote-'||suffix));
 update lumo_private.accounts set status='suspended' where id=outside_account;
 select count(*) into before_count from lumo_private.journals;
 perform pg_temp.group_as(bob_id,bob_session);
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-failure-final-vote-'||suffix));
 perform pg_temp.group_assert(result->>'code'='ACCOUNT_UNAVAILABLE' and (select count(*) from lumo_private.group_approvals where proposal_id=pid)=1,'failed final posting rolls back that approval');
 perform pg_temp.group_assert((select count(*) from lumo_private.journals)=before_count and (select balance from lumo_private.accounts where id=group_account)=6000,'failed payout changes neither ledger nor group balance');
 update lumo_private.accounts set status='active' where id=outside_account;
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.payout.cancel',jsonb_build_object('groupId',gid,'proposalId',pid,'attemptId','group-failure-cancel-'||suffix));
 -- Expired proposals cannot execute even with a fresh PIN and attempt.
 result:=pg_temp.group_call('group.payout.request',jsonb_build_object('groupId',gid,'recipientHandle',outside_handle,'amount',500,'pin',pin,'attemptId','group-expired-request-'||suffix));pid:=(result->>'proposalId')::uuid;
 update lumo_private.group_payouts set created_at=clock_timestamp()-interval '2 days',expires_at=clock_timestamp()-interval '1 day' where id=pid;
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid,'proposalId',pid,'pin',pin,'attemptId','group-expired-approve-'||suffix));
 perform pg_temp.group_assert(result->>'code'='PAYOUT_UNAVAILABLE','expired payout cannot collect approvals or move money');
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.close',jsonb_build_object('groupId',gid,'attemptId','group-close-nonzero-'||suffix));perform pg_temp.group_assert(result->>'code'='GROUP_BALANCE','ordinary close cannot discard nonzero balance');
 update lumo_private.accounts set status='suspended' where id=alice_account;
 select count(*) into before_count from lumo_private.journals;
 result:=pg_temp.group_call('group.cancel',jsonb_build_object('groupId',gid,'pin',pin,'attemptId','group-cancel-unavailable-'||suffix));
 perform pg_temp.group_assert(result->>'code'='ACCOUNT_UNAVAILABLE' and (select count(*) from lumo_private.journals)=before_count and (select balance from lumo_private.accounts where id=group_account)=6000,'unavailable contributor rolls back the entire cancellation refund batch');
 perform pg_temp.group_assert((select status from lumo_private.groups where id=gid)='open','failed refund batch keeps group open and recoverable');
 update lumo_private.accounts set status='active' where id=alice_account;
 result:=pg_temp.group_call('group.cancel',jsonb_build_object('groupId',gid,'pin',pin,'attemptId','group-cancel-refund-'||suffix));first_result:=result;
 perform pg_temp.group_assert(result->>'ok'='true' and result#>>'{group,status}'='cancelled' and (result->>'refunded')::bigint=6000 and jsonb_array_length(result->'receipts')=3,'cancel refunds all original contributors and preserves history');
 perform pg_temp.group_assert((select sum((x->>'amount')::bigint) from jsonb_array_elements(result->'receipts')x)=6000 and (select balance from lumo_private.accounts where id=group_account)=0,'cancellation conserves every remaining pesewa');
 perform pg_temp.group_assert((select balance from lumo_private.accounts where id=owner_account)=11000 and (select balance from lumo_private.accounts where id=alice_account)=8800 and (select balance from lumo_private.accounts where id=bob_account)=9200,'pro-rata cancellation returns 50/30/20 percent of remaining funds');
 result:=pg_temp.group_call('group.cancel',jsonb_build_object('groupId',gid,'pin',pin,'attemptId','group-cancel-refund-'||suffix));perform pg_temp.group_assert(result->>'replayed'='true' and result->'receipts'=first_result->'receipts','cancellation retry never refunds twice');
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid,'amount',100,'pin',pin,'attemptId','group-after-cancel-'||suffix));perform pg_temp.group_assert(result->>'code'='GROUP_CLOSED','cancelled group cannot receive more money');
 -- Three pesewas prove deterministic rounding after a partial payout.
 result:=pg_temp.group_call('group.create',jsonb_build_object('name','Rounding','approvalCount',1,'approvalThreshold',1000,'attemptId','group-round-create-'||suffix));gid2:=(result->>'groupId')::uuid;code:=result#>>'{group,joinCode}';
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid2,'amount',1,'pin',pin,'attemptId','group-round-owner-'||suffix));
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.join',jsonb_build_object('code',code,'attemptId','group-round-join-'||suffix));
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid2,'amount',2,'pin',pin,'attemptId','group-round-alice-'||suffix));
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.payout.request',jsonb_build_object('groupId',gid2,'recipientHandle',outside_handle,'amount',1,'pin',pin,'attemptId','group-round-payout-'||suffix));pid:=(result->>'proposalId')::uuid;
 perform pg_temp.group_as(alice_id,alice_session);
 result:=pg_temp.group_call('group.payout.approve',jsonb_build_object('groupId',gid2,'proposalId',pid,'pin',pin,'attemptId','group-round-approve-'||suffix));
 perform pg_temp.group_as(owner_id,owner_session);
 result:=pg_temp.group_call('group.cancel',jsonb_build_object('groupId',gid2,'pin',pin,'attemptId','group-round-cancel-'||suffix));
 perform pg_temp.group_assert((result->>'refunded')::bigint=2 and jsonb_array_length(result->'receipts')=2 and (select sum((x->>'amount')::bigint) from jsonb_array_elements(result->'receipts')x)=2,'largest-remainder refund preserves indivisible pesewas');
 perform pg_temp.group_assert((select min((x->>'amount')::bigint) from jsonb_array_elements(result->'receipts')x)=1,'rounding distributes one pesewa to each original contributor');
 -- Deadline blocks new money but retains history and valid cancellation.
 result:=pg_temp.group_call('group.create',jsonb_build_object('name','Deadline','attemptId','group-deadline-create-'||suffix));gid3:=(result->>'groupId')::uuid;
 update lumo_private.groups set deadline=clock_timestamp()-interval '1 minute' where id=gid3;
 result:=pg_temp.group_call('group.contribute',jsonb_build_object('groupId',gid3,'amount',100,'pin',pin,'attemptId','group-deadline-pay-'||suffix));perform pg_temp.group_assert(result->>'code'='GROUP_DEADLINE','expired deadline rejects new contribution');
 result:=pg_temp.group_call('group.close',jsonb_build_object('groupId',gid3,'attemptId','group-deadline-close-'||suffix));perform pg_temp.group_assert(result->>'ok'='true' and result#>>'{group,status}'='closed','zero-balance group closes preserving history');
 perform pg_temp.group_assert(not has_function_privilege('authenticated','lumo_private.groups_command(text,jsonb)','EXECUTE') and not has_function_privilege('anon','lumo_private.group_json(uuid,uuid,boolean)','EXECUTE'),'private helpers cannot bypass guarded dispatcher');
 perform pg_temp.group_assert(not has_table_privilege('authenticated','lumo_private.group_members','SELECT') and (select bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='lumo_private' and c.relname in ('groups','group_members','group_messages','group_payouts','group_approvals','group_postings')),'all group records private with RLS');
 perform pg_temp.group_assert((select coalesce(sum(amount),0) from lumo_private.entries)=0,'all shared ledger entries conserve funds');
 delete from auth.sessions where id=owner_session;
 result:=pg_temp.group_call('group.list');perform pg_temp.group_assert(result->>'code'='SESSION_REVOKED','revoked session cannot read groups');
 perform set_config('lumo.group.report',jsonb_build_object('checks',current_setting('lumo.group.checks')::integer,'fixturesRolledBack',true,'groupBalanceAfterCancel',0,'realCrossAccountLedger',true)::text,true);
 perform pg_temp.group_as(alice_id,alice_session);
end $$;
set local role authenticated;
set constraints all immediate;
select current_setting('lumo.group.report')::jsonb as connected_groups_test;
rollback;
